        LevelReferralControllerV2.setEnableNextEpoch(true);
        LevelReferralControllerV2.nextEpoch();
        vm.stopPrank();
        vm.warp(block.timestamp + 60 * 60);
        claim();
        vm.warp(block.timestamp + 5 * 60 * 60);
